                approver3_checked = "0";
            }
            continue;
        }
        
        if (eleName == "approver4_required") {
            if(ele.checked)
            {
                approver4_checked = "1";
            }
            else
            {
                approver4_checked = "0";
            }
            continue;
        }
        
        if (eleName == "approver5_required") {
            if(ele.checked)
            {
                approver5_checked = "1";
            }
            else
            {
                approver5_checked = "0";
            }
            continue;
        }
    }
    
    strresult += strcreater1+",";
    strresult += strcreater2+",";
    strresult += strcreater3+",";
    strresult += strcreater4+",";
    strresult += strcreater5+",";
    strresult += strreviewer1+",";
    strresult += strreviewer2+",";
    strresult += strreviewer3+",";
    strresult += strreviewer4+",";
    strresult += strreviewer5+",";
    strresult += strapprover1+",";
    strresult += strapprover2+",";
    strresult += strapprover3+",";
    strresult += strapprover4+",";
    strresult += strapprover5+",";
    strresult += creater1_checked+",";
    strresult += creater2_checked+",";
    strresult += creater3_checked+",";
    strresult += creater4_checked+",";
    strresult += creater5_checked+",";
    strresult += reviewer1_checked+",";
    strresult += reviewer2_checked+",";
    strresult += reviewer3_checked+",";
    strresult += reviewer4_checked+",";
    strresult += reviewer5_checked+",";
    strresult += approver1_checked+",";
    strresult += approver2_checked+",";
    strresult += approver3_checked+",";
    strresult += approver4_checked+",";
    strresult += approver5_checked;
    
    // ダイアログクローズ処理（カンマ[,]区切り文字列、0-4:creater1-5,5-9:reviewer1-5,10-14:approver1-5,15-19:createrrequired,20-24:reviewerrequired,25-29:approverrequired)
    parent.dialogArguments.dialog.close(strresult);

return;
